# Patch the libMesh FE sources in place for NEDELEC_ONE on 3D cells:
#   - FIRST order on PRISM15/18/20/21 and PYRAMID13/14/18 (upstream: TET10/14, HEX20/27 only);
#   - SECOND order on TET14, HEX27, PRISM20/21 and PYRAMID18.
# The shape function code is in nedelec_one_3D/, generated by nedelec_one_3D/generator/generate.py.
#
# Usage: patch_nedelec_one_3D.py <libMesh source dir>
import pathlib
import re
import sys

root = pathlib.Path(sys.argv[1])
FRAGMENTS = pathlib.Path(__file__).resolve().parent / 'nedelec_one_3D'

# ---------------------------------------------------------------- helpers
SEP = r'(?:\s|//[^\n]*(?:\n|$))'   # whitespace or // comments


def _isword(c):
    return c.isalnum() or c == '_'


def ws(snippet):
    """Regex matching `snippet` regardless of whitespace/newlines/comments between tokens."""
    toks = re.findall(r'\w+|[^\w\s]', snippet)
    out = []
    for i, t in enumerate(toks):
        if i:
            need = _isword(toks[i - 1][-1]) and _isword(t[0])
            out.append(SEP + ('+' if need else '*'))
        out.append(re.escape(t))
    return ''.join(out)


def die(msg):
    print('ERROR (libMesh patch): ' + msg, file=sys.stderr)
    sys.exit(1)


def fragment(name):
    return (FRAGMENTS / name).read_text()


def edit(text, where, name, pattern, block, count=1):
    """Insert block after/before each match of pattern, or replace it; exactly `count` matches."""
    ms = list(re.finditer(pattern, text))
    if len(ms) != count:
        die(f'{where}: anchor "{name}" matched {len(ms)} times (expected {count}). '
            'Upstream code changed; update the patch.')
    for m in reversed(ms):
        if block[0] == 'after':
            text = text[:m.end()] + block[1] + text[m.end():]
        elif block[0] == 'before':
            text = text[:m.start()] + block[1] + text[m.start():]
        elif block[0] == 'replace':
            text = text[:m.start()] + block[1] + text[m.end():]
        else:
            die('bad where')
    print(f'  patched {where}: {name}')
    return text


def read(rel):
    path = root / rel
    if not path.is_file():
        die(f'{rel} not found')
    return path, path.read_text()


def function_span(text, signature, where):
    """[start, end) of the function definition starting with `signature`, up to the next template <>."""
    ms = list(re.finditer(signature, text))
    if len(ms) != 1:
        die(f'{where}: function "{signature}" matched {len(ms)} times (expected 1).')
    start = ms[0].start()
    nxt = re.compile(r'\ntemplate\s*<>').search(text, ms[0].end())
    return start, nxt.start() if nxt else len(text)


def edit_function(text, where, signature, edits):
    start, end = function_span(text, signature, where)
    body = text[start:end]
    for name, pattern, block in edits:
        body = edit(body, where, name, pattern, block)
    return text[:start] + body + text[end:]


# The face degrees of freedom follow Elem::oriented_face_vertices()
_, elem_h = read('include/geom/elem.h')
if 'oriented_face_vertices' not in elem_h:
    die('Elem::oriented_face_vertices() not found: libMesh is older than the patch needs.')

# ------------------------------------------------------------ fe_interface.C
path, text = read('src/fe/fe_interface.C')
text = edit(text, 'fe_interface.C', 'max_order NEDELEC_ONE',
            ws('case NEDELEC_ONE: switch (el_t) { case TRI6: case TRI7: case QUAD8: case QUAD9: '
               'return 5; case TET10: case TET14: case HEX20: case HEX27: return 1;'),
            ('replace', '''case NEDELEC_ONE:
      switch (el_t)
        {
        case TRI6:
        case TRI7:
        case QUAD8:
        case QUAD9:
          return 5;
        case TET10:
        case HEX20:
        case PRISM15:
        case PRISM18:
        case PYRAMID13:
        case PYRAMID14:
          return 1;
        case TET14:
        case HEX27:
        case PRISM20:
        case PRISM21:
        case PYRAMID18:
          return 2;'''))
path.write_text(text)

# ------------------------------------------------------------ fe_nedelec_one.C
path, text = read('src/fe/fe_nedelec_one.C')
if 'PRISM' in text or 'PYRAMID' in text:
    die('fe_nedelec_one.C already mentions prisms or pyramids: upstream changed; update the patch.')

text = edit(text, 'fe_nedelec_one.C', 'nodal_soln element types',
            ws('elem_type != HEX20 && elem_type != HEX27') + r'(?=\s*\))',
            ('after', ''' &&
      elem_type != PRISM15 && elem_type != PRISM18 &&
      elem_type != PRISM20 && elem_type != PRISM21 &&
      elem_type != PYRAMID13 && elem_type != PYRAMID14 &&
      elem_type != PYRAMID18'''))

text = edit(text, 'fe_nedelec_one.C', 'n_dofs',
            ws('return 3*o*(o+1)*(o+1);'),
            ('after', '''
    case PRISM15:
    case PRISM18:
      libmesh_assert_less (o, 2);
      libmesh_fallthrough();
    case PRISM20:
    case PRISM21:
      return 3*o*(o+1)*(o+2)/2;
    case PYRAMID13:
    case PYRAMID14:
      libmesh_assert_less (o, 2);
      libmesh_fallthrough();
    case PYRAMID18:
      return o*(3*o*o+5);'''))

text = edit(text, 'fe_nedelec_one.C', 'n_dofs_at_node',
            ws('case 26: libmesh_assert_equal_to(t, HEX27); return 0; '
               'default: libmesh_error_msg("ERROR: Invalid node ID " << n); } }'),
            ('after', '''
    case PRISM15:
    case PRISM18:
      libmesh_assert_less (o, 2);
      libmesh_fallthrough();
    case PRISM20:
    case PRISM21:
      {
        switch (n)
          {
          case 0:
          case 1:
          case 2:
          case 3:
          case 4:
          case 5:
            return 0;
          case 6:
          case 7:
          case 8:
          case 9:
          case 10:
          case 11:
          case 12:
          case 13:
          case 14:
            return o;
          case 15:
          case 16:
          case 17:
            libmesh_assert_not_equal_to(t, PRISM15);
            return 2*o*(o-1);
          case 18:
          case 19:
            libmesh_assert(t == PRISM20 || t == PRISM21);
            return o*(o-1);
          case 20:
            libmesh_assert_equal_to(t, PRISM21);
            return 0;
          default:
            libmesh_error_msg("ERROR: Invalid node ID " << n);
          }
      }
    case PYRAMID13:
    case PYRAMID14:
      libmesh_assert_less (o, 2);
      libmesh_fallthrough();
    case PYRAMID18:
      {
        switch (n)
          {
          case 0:
          case 1:
          case 2:
          case 3:
          case 4:
            return 0;
          case 5:
          case 6:
          case 7:
          case 8:
          case 9:
          case 10:
          case 11:
          case 12:
            return o;
          case 13:
            libmesh_assert_not_equal_to(t, PYRAMID13);
            return 2*o*(o-1);
          case 14:
          case 15:
          case 16:
          case 17:
            libmesh_assert_equal_to(t, PYRAMID18);
            return o*(o-1);
          default:
            libmesh_error_msg("ERROR: Invalid node ID " << n);
          }
      }'''))

text = edit(text, 'fe_nedelec_one.C', 'n_dofs_per_elem',
            ws('return 3*o*(o-1)*(o-1);'),
            ('after', '''
    case PRISM15:
    case PRISM18:
      libmesh_assert_less (o, 2);
      libmesh_fallthrough();
    case PRISM20:
    case PRISM21:
      return o*(o-1)*(3*o-4)/2;
    case PYRAMID13:
    case PYRAMID14:
      libmesh_assert_less (o, 2);
      libmesh_fallthrough();
    case PYRAMID18:
      return 3*o*(o-1)*(o-1);'''))
path.write_text(text)

# ------------------------------------------------------ fe_nedelec_one_shape_3D.C
where = 'fe_nedelec_one_shape_3D.C'
path, text = read('src/fe/' + where)
if re.search(r'\bPRISM|\bPYRAMID|case\s+SECOND\b', text):
    die(f'{where} already has prisms, pyramids or second order: upstream changed; update the patch.')

text = edit(text, where, 'includes', ws('#include "libmesh/enum_to_string.h"') + r'\n',
            ('after', '\n// C++ includes\n#include <algorithm> // std::max\n#include <array>\n'))
text = edit(text, where, 'face coefficients helper', r'namespace libMesh\s*\{\n',
            ('after', '\n' + fragment('face_coefficients.C')))

# The degrees of freedom on an edge follow its orientation as in 2D: the sign, and the
# reversed index ii along the edge from order two on
SIGN_II = ('replace',
           'const char sign = i >= totalorder * elem->n_edges() || '
           'elem->positive_edge_orientation(i / totalorder) ? 1 : -1;\n'
           '  const unsigned int ii = sign > 0 ? i : (i / totalorder * 2 + 1) * totalorder - 1 - i;')
SIGN = ws('const char sign = elem->positive_edge_orientation(i) ? 1 : -1;')
UNSUPPORTED = r'[ \t]*// unsupported order\s*\n\s*default:\s*libmesh_error_msg\("ERROR: Unsupported 3D FE order!: "'

text = edit_function(text, where, ws('RealGradient FE<3,NEDELEC_ONE>::shape(const Elem * elem'), [
    ('shape: sign and ii', SIGN, SIGN_II),
    ('shape: FIRST prism and pyramid',
     ws('case 5: return sign * RealGradient( 0.0, zeta, -eta ); '
        'default: libmesh_error_msg("Invalid i = " << i); } }') + r'\n',
     ('after', '\n' + fragment('first_shape.C'))),
    ('shape: SECOND', UNSUPPORTED, ('before', fragment('second_shape.C'))),
])

text = edit_function(text, where, ws('RealGradient FE<3,NEDELEC_ONE>::shape_deriv(const Elem * elem'), [
    ('shape_deriv: sign and ii', SIGN, SIGN_II),
    ('shape_deriv: FIRST prism and pyramid',
     ws('case 3: return sign * RealGradient( -1.0, -1.0, 0.0 ); '
        'case 4: return sign * RealGradient( 1.0, 0.0, 0.0 ); '
        'default: libmesh_error_msg("Invalid i = " << i); } } '
        'default: libmesh_error_msg("Invalid j = " << j); } }') + r'\n',
     ('after', '\n' + fragment('first_shape_deriv.C'))),
    ('shape_deriv: SECOND', UNSUPPORTED, ('before', fragment('second_shape_deriv.C'))),
])

text = edit_function(text, where, ws('RealGradient FE<3,NEDELEC_ONE>::shape_second_deriv(const Elem * elem'), [
    ('shape_second_deriv: named point', ws('const Point &,') + r'(?=\s*const bool add_p_level\))',
     ('replace', 'const Point & p,')),
    ('shape_second_deriv: sign, ii and coordinates', SIGN,
     (SIGN_II[0], SIGN_II[1] + '\n\n  const Real xi   = p(0);\n  const Real eta  = p(1);\n'
      '  const Real zeta = p(2);')),
    # Upstream bug fix: the signs of d^2/dxidzeta of shape 3 and d^2/detadzeta of shape 2 of the
    # FIRST order hexahedron (shapes 3: (0, -(1-xi-zeta+xi*zeta)/8, 0), 2: ((1+eta-zeta-eta*zeta)/8, 0, 0))
    ('shape_second_deriv: FIRST HEX d^2/dxidzeta of shape 3',
     ws('case 1: case 3: case 11: return sign * RealGradient( 0.0, 0.125 );'),
     ('replace', '''case 1:
                      case 11:
                        return sign * RealGradient( 0.0, 0.125 );
                      case 3:''')),
    ('shape_second_deriv: FIRST HEX d^2/detadzeta of shape 2',
     ws('case 2: case 8: case 10: return sign * RealGradient( 0.125, 0.0, 0.0 );'),
     ('replace', '''case 2:
                        return sign * RealGradient( -0.125, 0.0, 0.0 );
                      case 8:
                      case 10:
                        return sign * RealGradient( 0.125, 0.0, 0.0 );''')),
    ('shape_second_deriv: FIRST prism and pyramid',
     ws('case TET10: case TET14: return RealGradient();') + r'\n',
     ('after', '\n' + fragment('first_shape_second_deriv.C'))),
    ('shape_second_deriv: SECOND', UNSUPPORTED, ('before', fragment('second_shape_second_deriv.C'))),
])
path.write_text(text)

print('libMesh NEDELEC_ONE 3D patch applied.')
